implementation.script:
var taskID = tw.local.Task_ID.split(".")[1];
if(!tw.local.isSuccessfull){
	var param = new tw.object.Map();
	param.put("Status","Failed");
	param.put("VersionNumber","");
	param.put("FailureReason",tw.local.errorMessageRPA);
	tw.system.findTaskByID(taskID).complete(tw.system.org.findUserByName("bawadmin"), param);
		
}
if(tw.local.timeout){
	var param = new tw.object.Map();
	param.put("Status","Failed");
	param.put("VersionNumber","");
	param.put("FailureReason","Timeout");
	tw.system.findTaskByID(taskID).complete(tw.system.org.findUserByName("bawadmin"), param);


	
}

var taskID = tw.local.taskId2.split(".")[1];
if(!tw.local.isSuccessfull){
	var param = new tw.object.Map();
	param.put("Status","Failed");
	param.put("VersionNumber","");
	param.put("FailureReason",tw.local.errorMessageRPA);
	tw.system.findTaskByID(taskID).complete(tw.system.org.findUserByName("bawadmin"), param);
		
}
if(tw.local.timeout2){
	var param = new tw.object.Map();
	param.put("Status","Failed");
	param.put("VersionNumber","");
	param.put("FailureReason","Timeout");
	tw.system.findTaskByID(taskID).complete(tw.system.org.findUserByName("bawadmin"), param);


	
}

if(tw.local.status1!="Success"){
	tw.local.status ="Failed";
	tw.local.failureReason = tw.local.failerReson1;
}
if(tw.local.status2!="Success"){
	tw.local.status ="Failed";
	tw.local.failureReason = tw.local.failerReson2;
}
